import pandas as pd

def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    numeric_cols = ['flipper_length_mm', 'body_mass_g', 'year']
    for col in numeric_cols:
        df[col] = pd.to_numeric(df[col], errors='coerce')
    df['sex'] = df['sex'].str.strip()
    df = df.dropna(subset=['sex'])
    return df

def answer(df):
    grouped = df.groupby('sex')['body_mass_g'].mean()
    return {k: v for k, v in grouped.items() if not pd.isna(v)}
